#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *storage;
    size_t capacity;     /* total slots (including one spare) */
    size_t length;       /* bytes currently stored */
    size_t head;         /* next write position */
    size_t tail;         /* next read position  */
};

ringbuf_t *rb_create(size_t capacity)
{
    if (capacity == 0)
        return NULL;

    ringbuf_t *rb = calloc(1, sizeof(*rb));
    if (!rb)
        return NULL;

    rb->storage = malloc(capacity);
    if (!rb->storage) {
        free(rb);
        return NULL;
    }

    rb->capacity = capacity;
    rb->length   = 0;
    rb->head     = 0;
    rb->tail     = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->storage);
    free(rb);
}

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->length;
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->length = 0;
    rb->head   = 0;
    rb->tail   = 0;
}

static inline void advance(ringbuf_t *rb, size_t *pos)
{
    (*pos)++;
    if (*pos == rb->capacity)
        *pos = 0;
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    if (!rb || !data || len == 0)
        return 0;

    if (rb->length == rb->capacity)
        return 0;

    /* How much can we write? */
    size_t avail = rb->capacity - rb->length;
    if (len > avail)
        len = avail;

    size_t written = len;

    /* First segment: from head to end of storage */
    size_t first = rb->capacity - rb->head;
    if (first < len) {
        memcpy(rb->storage + rb->head, data, first);
        advance(rb, &rb->head);
        data += first;
        len  -= first;
    } else {
        memcpy(rb->storage + rb->head, data, len);
        rb->head = (rb->head + len) % rb->capacity;
    }

    rb->length += written;
    return written;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0)
        return 0;

    if (rb->length == 0)
        return 0;

    size_t avail = rb->length;
    if (len > avail)
        len = avail;

    /* First segment: from tail to end of storage */
    size_t first = rb->capacity - rb->tail;
    if (first < len) {
        memcpy(out, rb->storage + rb->tail, first);
        out += first;
        rb->tail += first;
        rb->length -= first;

        /* Wrap-around: second segment */
        second:
        rb->tail = 0;   /* restart at beginning after wrapping */
    } else {
        memcpy(out, rb->storage + rb->tail, len);
        rb->tail += len;
        if (rb->tail == rb->capacity)
            rb->tail = 0;
        rb->length -= len;
    }

    return len;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0)
        return 0;

    if (rb->length == 0)
        return 0;

    if (len > rb->length)
        len = rb->length;

    /* Copy by advancing a local copy of tail without mutating state */
    size_t pos = rb->tail;
    for (size_t i = 0; i < len; i++) {
        out[i] = rb->storage[pos];
        pos++;
        if (pos == rb->capacity)
            pos = 0;
    }

    return len;
}

