#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include "ringbuf.h"

int main(void) {
    /* Test: create and destroy */
    ringbuf_t *rb = rb_create(0);
    assert(rb == NULL);

    ringbuf_t *rb5 = rb_create(5);
    assert(rb5 != NULL);
    assert(rb_size(rb5) == 0);
    assert(rb_capacity(rb5) == 5);
    rb_destroy(rb5);
    rb_destroy(NULL); /* Should not crash */

    /* Test: basic write/read with small buffer (wraps around end of data array) */
    ringbuf_t *rb3 = rb_create(3);
    assert(rb_capacity(rb3) == 3);

    const uint8_t a[] = {1, 2};
    size_t n = rb_write(rb3, a, 2);
    assert(n == 2);
    assert(rb_size(rb3) == 2);

    uint8_t buf[8] = {0};
    n = rb_read(rb3, buf, 2);
    assert(n == 2);
    assert(buf[0] == 1 && buf[1] == 2);
    assert(rb_size(rb3) == 0);

    /* Test: clear */
    const uint8_t b[] = {3, 4, 5};
    rb_write(rb3, b, 3);
    assert(rb_size(rb3) == 3);
    rb_clear(rb3);
    assert(rb_size(rb3) == 0);

    /* Test: read more than available */
    rb_write(rb3, b, 2); /* fills [3, 4] */
    n = rb_read(rb3, buf, 100);
    assert(n == 2);
    assert(buf[0] == 3 && buf[1] == 4);

    /* Test: full buffer */
    memset(buf, 0, sizeof(buf));
    n = rb_read(rb3, buf, 10);
    assert(n == 0);

    /* Test: wrap-around write (write past end of storage) */
    uint8_t data[4] = {10, 11, 12, 13};
    n = rb_write(rb3, data, 4);
    assert(n == 3); /* can only fit 3 in capacity-3 buffer (already has 1) */

    uint8_t out[4] = {0};
    n = rb_read(rb3, out, 4);

    assert(n == 4);
    assert(out[0] == 5 && out[1] == 10 && out[2] == 11 && out[3] == 12);

    /* Test: wrap-around read (read past end of storage) */
    rb_clear(rb3);
    /* Fill: [1, 2, empty, empty, empty] — head at pos 5 (wrapped), tail at 0 */
    const uint8_t c[] = {1, 2, 3};
    rb_write(rb3, c, 3); /* fills all slots */

    rb_clear(rb3);
    const uint8_t d[] = {6, 7};
    rb_write(rb3, d, 2);       /* pos 0: 2 bytes -> head = 2 */

    rb_clear(rb3);
    const uint8_t e[] = {1, 2};
    rb_write(rb3, e, 2);       /* tail=0, head=2 */

    const uint8_t f[] = {3, 4};
    rb_write(rb3, f, 2);       /* wraps: byte at pos 2 (end), byte at pos 0 (wrap) -> overflow not possible because buffer is capacity! */
    /* Wait, let me reconsider - with a cap-3 buffer full of [1,2] and head=2, 
